"""Parse and format compact duration strings."""

import re


_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate(_UNIT_SECONDS)}
_PARTS_RE = re.compile(r"\d+[dhms](?:(?: +| *, *)?\d+[dhms])*")


def parse(text):
    """Return the number of seconds represented by a duration string.

    Parts are ordered from days through seconds, and may be adjacent,
    separated by spaces, or separated by commas with optional surrounding
    spaces.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    stripped = text.strip(" ")
    if not stripped or _PARTS_RE.fullmatch(stripped) is None:
        raise ValueError("invalid duration")

    total = 0
    previous_order = -1
    for number, unit in re.findall(r"(\d+)([dhms])", stripped):
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("units must appear once in descending order")
        previous_order = order
        total += int(number) * _UNIT_SECONDS[unit]
    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds compactly."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")
    if not isinstance(largest, str) or largest not in _UNIT_SECONDS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_UNIT_SECONDS)
    start = units.index(largest)
    remainder = seconds
    parts = []
    for unit in units[start:]:
        value, remainder = divmod(remainder, _UNIT_SECONDS[unit])
        if value:
            parts.append(f"{value}{unit}")
    return "".join(parts) if parts else "0s"

import unittest

from durations import format, parse


class ParseTests(unittest.TestCase):
    def test_adjacent_parts_and_units(self):
        self.assertEqual(parse("1h30m"), 5400)
        self.assertEqual(parse("1d2h3m4s"), 93784)

    def test_single_unit_and_large_unit_values(self):
        self.assertEqual(parse("90s"), 90)
        self.assertEqual(parse("90m"), 5400)

    def test_spaces_and_commas(self):
        self.assertEqual(parse(" 2d 4h "), 187200)
        self.assertEqual(parse("1h, 30m"), 5400)
        self.assertEqual(parse("1h ,30m"), 5400)

    def test_leading_zeroes_and_zero_parts(self):
        self.assertEqual(parse("001d02h003m0004s"), 93784)
        self.assertEqual(parse("0d0h0m0s"), 0)

    def test_rejects_invalid_values(self):
        for value in (
            "", "   ", "-1s", "1.5h", "12", "1x", "1h1h",
            "1m1h", "1s1m", "1h,", ",1h", "1h,,2m", "1h, ,2m",
            "1h\t2m", "1h\n2m", "1 h", "1h 2", "1h-2m",
        ):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse(value)

    def test_non_string_rejected(self):
        with self.assertRaises(ValueError):
            parse(None)


class FormatTests(unittest.TestCase):
    def test_standard_formats(self):
        self.assertEqual(format(3661), "1h1m1s")
        self.assertEqual(format(86400), "1d")
        self.assertEqual(format(0), "0s")

    def test_zero_units_are_omitted(self):
        self.assertEqual(format(3600), "1h")
        self.assertEqual(format(60), "1m")
        self.assertEqual(format(86401), "1d1s")

    def test_largest_unit(self):
        self.assertEqual(format(90061, largest="h"), "25h1m1s")
        self.assertEqual(format(86400, largest="m"), "1440m")
        self.assertEqual(format(61, largest="s"), "61s")
        self.assertEqual(format(0, largest="h"), "0s")

    def test_invalid_seconds_rejected(self):
        for value in (-1, 1.5, "60", None, True, False):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    format(value)

    def test_invalid_largest_rejected(self):
        for value in ("x", "D", "", None, 1):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    format(10, largest=value)


