import re


_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_ORDER = "dhms"
_PART = re.compile(r"([0-9]+)([dhms])")


def parse(text):
    """Parse a duration string into whole seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    # Parse a part, then a separator and another part, until the input ends.
    total = 0
    last_unit_index = -1
    pos = 0
    length = len(text)

    while pos < length:
        match = _PART.match(text, pos)
        if match is None:
            raise ValueError("invalid duration")

        amount = int(match.group(1))
        unit = match.group(2)
        unit_index = _ORDER.index(unit)
        if unit_index <= last_unit_index:
            raise ValueError("units must be in descending order without repeats")
        last_unit_index = unit_index
        total += amount * _UNITS[unit]
        pos = match.end()

        if pos == length:
            break

        # A separator is either one or more spaces, or a comma with optional
        # spaces on either side. Commas therefore cannot trail or repeat.
        start = pos
        while pos < length and text[pos] == " ":
            pos += 1
        had_spaces_before = pos > start

        if pos < length and text[pos] == ",":
            pos += 1
            while pos < length and text[pos] == " ":
                pos += 1
        elif not had_spaces_before:
            raise ValueError("duration parts must be separated")

        if pos == length:
            raise ValueError("duration cannot end with a separator")

    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds as a compact duration."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if largest not in _UNITS:
        raise ValueError("largest must be one of d, h, m, s")

    start = _ORDER.index(largest)
    remainder = seconds
    parts = []
    for unit in _ORDER[start:]:
        value = _UNITS[unit]
        count, remainder = divmod(remainder, value)
        if count:
            parts.append(f"{count}{unit}")

    return "".join(parts) if parts else "0s"

