"""Utilities for parsing and formatting durations."""

import re


_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate(_UNIT_SECONDS)}


def parse(text):
    """Parse a duration string into whole seconds.

    Parts may be adjacent, separated by whitespace, or separated by a comma
    with optional surrounding whitespace. Units must occur in descending
    order, with no unit repeated.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    parts = re.findall(r"([0-9]+)([dhms])", text)
    if not parts:
        raise ValueError("invalid duration")

    # Check that the matches account for the complete input, allowing only
    # adjacency, whitespace, or a comma (with optional whitespace) between
    # parts. This also rejects leading, trailing, and repeated commas.
    position = 0
    total = 0
    previous_order = -1
    for number, unit in parts:
        match = re.search(r"([0-9]+)([dhms])", text[position:])
        if match is None:
            raise ValueError("invalid duration")
        start = position + match.start()
        end = position + match.end()
        separator = text[position:start]
        if separator and not (
            separator.isspace()
            or re.fullmatch(r"\s*,\s*", separator)
        ):
            raise ValueError("invalid separator")
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("units must be unique and in descending order")
        previous_order = order
        total += int(number) * _UNIT_SECONDS[unit]
        position = end

    if position != len(text):
        raise ValueError("invalid duration")
    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds as a duration."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")
    if largest not in _UNIT_SECONDS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_UNIT_SECONDS)
    units = units[_UNIT_ORDER[largest]:]
    if seconds == 0:
        return "0s"

    result = []
    remaining = seconds
    for unit in units:
        value, remaining = divmod(remaining, _UNIT_SECONDS[unit])
        if value:
            result.append(f"{value}{unit}")
    return "".join(result)

