import re


_UNITS = {"d": 86_400, "h": 3_600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate(_UNITS)}

# Parts are separated by whitespace, or by a comma with optional whitespace.
_PART = re.compile(r"([0-9]+)([dhms])")


def parse(text):
    """Parse an ordered duration string and return its length in seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    total = 0
    previous_order = -1
    position = 0
    first = True

    while position < len(text):
        if not first:
            separator = re.match(r"(?:\s+|\s*,\s*)", text[position:])
            if separator is None:
                raise ValueError("duration parts must be separated")
            position += separator.end()
            if position == len(text):
                raise ValueError("duration cannot end with a separator")

        part = _PART.match(text, position)
        if part is None:
            raise ValueError("invalid duration part")

        amount = int(part.group(1))
        unit = part.group(2)
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("units must appear once in descending order")

        total += amount * _UNITS[unit]
        previous_order = order
        position = part.end()
        first = False

    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds as a compact duration."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if largest not in _UNITS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_UNITS.items())
    start = next(index for index, (unit, _) in enumerate(units) if unit == largest)
    remaining = seconds
    parts = []
    for unit, size in units[start:]:
        amount, remaining = divmod(remaining, size)
        if amount:
            parts.append(f"{amount}{unit}")

    return "".join(parts) if parts else "0s"

