import re


_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_ORDER = {unit: index for index, unit in enumerate(_UNITS)}
_PART = re.compile(r"([0-9]+)([dhms])")


def parse(text):
    """Parse an ordered duration string and return its length in seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    total = 0
    last_order = -1
    position = 0
    length = len(text)

    while position < length:
        match = _PART.match(text, position)
        if match is None:
            raise ValueError("invalid duration")

        amount = int(match.group(1))
        unit = match.group(2)
        order = _ORDER[unit]
        if order <= last_order:
            raise ValueError("units must appear once in descending order")
        last_order = order
        total += amount * _UNITS[unit]
        position = match.end()

        if position == length:
            break

        # Parts can touch, be separated by whitespace, or be separated by a
        # comma with optional whitespace on either side.
        before_space = position
        while position < length and text[position].isspace():
            position += 1
        had_space = position > before_space

        if position < length and text[position] == ",":
            position += 1
            while position < length and text[position].isspace():
                position += 1
            if position == length:
                raise ValueError("comma must be between duration parts")
        elif not had_space and position == before_space:
            # No separator is also valid (for example, "1d2h").
            pass

        if position >= length or _PART.match(text, position) is None:
            raise ValueError("invalid duration separator or part")

    return total


def format(seconds, largest="d"):
    """Format a non-negative integer duration using units at or below largest."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")
    if largest not in _UNITS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_UNITS.items())
    start = next(index for index, (unit, _) in enumerate(units) if unit == largest)
    parts = []
    remainder = seconds

    for unit, scale in units[start:]:
        amount, remainder = divmod(remainder, scale)
        if amount:
            parts.append(f"{amount}{unit}")

    return "".join(parts) if parts else "0s"

