import re


_PARTS_RE = re.compile(r" *\d+[dhms](?:(?: +| *, *)\d+[dhms])* *\Z")
_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate(_UNITS)}


def _digits_to_int(digits):
    """Convert decimal digits without imposing Python's string-to-int limit."""
    value = 0
    for digit in digits:
        value = value * 10 + (ord(digit) - ord("0"))
    return value


def parse(text):
    """Return the whole-second length of a duration string.

    Parts must use descending, unique units (d, h, m, s). They may be
    separated by spaces or commas, with optional spaces around commas.
    """
    if not isinstance(text, str) or not _PARTS_RE.fullmatch(text):
        raise ValueError("invalid duration")

    parts = re.findall(r"(\d+)([dhms])", text)
    previous_order = -1
    total = 0
    for digits, unit in parts:
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("duration units must be unique and descending")
        previous_order = order
        total += _digits_to_int(digits) * _UNITS[unit]
    return total


def format(seconds, largest="d"):
    """Return a non-negative integer duration in compact form."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if largest not in _UNITS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_UNITS.items())
    start = _UNIT_ORDER[largest]
    remaining = seconds
    result = []
    for unit, size in units[start:]:
        amount, remaining = divmod(remaining, size)
        if amount:
            result.append(f"{amount}{unit}")
    return "".join(result) if result else "0s"

