_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate(_UNITS)}
_PART = re.compile(r"([0-9]+)([dhms])")


def parse(text):
    """Parse a duration string and return its length in whole seconds.

    Parts must use units in descending order. Parts may be separated by
    spaces, or by a comma with optional surrounding spaces.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    source = text.strip(" ")
    if not source:
        raise ValueError("duration must not be empty")

    position = 0
    previous_order = -1
    total = 0

    while position < len(source):
        match = _PART.match(source, position)
        if match is None:
            raise ValueError("invalid duration part")

        amount = int(match.group(1))
        unit = match.group(2)
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("duration units must appear once in descending order")
        previous_order = order
        total += amount * _UNITS[unit]
        position = match.end()

        if position == len(source):
            break

        # Consume spaces surrounding a separator. Spaces alone are a valid
        # separator; a comma is also valid, but must have parts on both sides.
        had_space = False
        while position < len(source) and source[position] == " ":
            had_space = True
            position += 1

        if position < len(source) and source[position] == ",":
            position += 1
            while position < len(source) and source[position] == " ":
                position += 1
            if position == len(source):
                raise ValueError("comma must be between duration parts")
        elif not had_space:
            raise ValueError("duration parts must be separated")

    return total


