import re


_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {"d": 0, "h": 1, "m": 2, "s": 3}
_PARTS_RE = re.compile(r"\s*[0-9]+[dhms](?:(?:\s*,\s*|\s+)[0-9]+[dhms])*\s*\Z")


def _decimal_to_int(digits):
    """Convert decimal digits without Python's string-to-int size limit."""
    value = 0
    for digit in digits:
        value = value * 10 + ord(digit) - ord("0")
    return value


def _int_to_decimal(value):
    """Convert a non-negative int without Python's int-to-string size limit."""
    if value == 0:
        return "0"
    # Convert in base-10 chunks small enough for Python's regular conversion.
    base = 10 ** 9
    chunks = []
    while value:
        value, remainder = divmod(value, base)
        chunks.append(remainder)
    return str(chunks[-1]) + "".join(f"{chunk:09d}" for chunk in reversed(chunks[:-1]))


def parse(text):
    """Parse a duration string and return its length in whole seconds."""
    if not isinstance(text, str) or not _PARTS_RE.fullmatch(text):
        raise ValueError("invalid duration")

    total = 0
    previous_order = -1
    for number, unit in re.findall(r"([0-9]+)([dhms])", text):
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("duration units must appear once in descending order")
        previous_order = order
        total += _decimal_to_int(number) * _UNIT_SECONDS[unit]
    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds as a compact duration."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if largest not in _UNIT_ORDER:
        raise ValueError("largest must be one of 'd', 'h', 'm', or 's'")

    start = _UNIT_ORDER[largest]
    remaining = seconds
    parts = []
    for unit in ("d", "h", "m", "s")[start:]:
        amount, remaining = divmod(remaining, _UNIT_SECONDS[unit])
        if amount:
            parts.append(_int_to_decimal(amount) + unit)
    return "".join(parts) if parts else "0s"

