"""Parse and format compact duration strings."""

import re


_PARTS = {"d": 86_400, "h": 3_600, "m": 60, "s": 1}
_ORDER = {unit: index for index, unit in enumerate(_PARTS)}
_PARSE_RE = re.compile(r" *[0-9]+[dhms](?:(?: +| *, *)[0-9]+[dhms])* *\Z")


def parse(text):
    """Return the whole-second length represented by *text*.

    Parts must use the units d, h, m, and s in that order. Parts can be
    separated by spaces or by a comma with optional surrounding spaces.
    """
    if not isinstance(text, str) or not _PARSE_RE.fullmatch(text):
        raise ValueError("invalid duration")

    total = 0
    previous = -1
    for number, unit in re.findall(r"([0-9]+)([dhms])", text):
        order = _ORDER[unit]
        if order <= previous:
            raise ValueError("duration units must be unique and in descending order")
        previous = order
        total += int(number) * _PARTS[unit]
    return total


def format(seconds, largest="d"):
    """Format a non-negative integer number of seconds as a compact duration."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if largest not in _PARTS:
        raise ValueError("largest must be one of d, h, m, or s")

    units = list(_PARTS)
    units = units[units.index(largest):]
    if seconds == 0:
        return "0s"

    result = []
    remainder = seconds
    for unit in units:
        value, remainder = divmod(remainder, _PARTS[unit])
        if value:
            result.append(f"{value}{unit}")
    return "".join(result)

import unittest

from durations import format, parse


class ParseTests(unittest.TestCase):
    def test_examples(self):
        cases = {
            "1h30m": 5400,
            "90s": 90,
            "2d 4h": 187200,
            "1d2h3m4s": 93784,
            "1h, 30m": 5400,
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                self.assertEqual(parse(text), expected)

    def test_whitespace_leading_zeros_and_unbounded_values(self):
        self.assertEqual(parse("  0002d, 00003h4s  "), 184804)
        self.assertEqual(parse("90m"), 5400)
        self.assertEqual(parse("999999999999999999999999s"), 999999999999999999999999)

    def test_rejects_invalid_syntax(self):
        for text in (
            "", "   ", "-1s", "1.5h", "12", "1w", "1h30m", "1h30m",
            "1m1h", "1h1h", "1s1m", "1h,,30m", ",1h", "1h,", "1h, ,30m",
            "1 h", "1h  ,30m", "1h,30m,", "1h\n30m", None,
        ):
            # A comma separator is valid with surrounding spaces; all other
            # examples here are malformed or have units in the wrong order.
            if text == "1h  ,30m":
                # Whitespace around a comma is explicitly allowed.
                self.assertEqual(parse(text), 5400)
            else:
                with self.subTest(text=text), self.assertRaises(ValueError):
                    parse(text)


